import{_ as s,o as n,c as a,a6 as p}from"./chunks/framework.BrkgobfX.js";const b=JSON.parse('{"title":"核心模块指令","description":"worker 进程与连接、events 块、error_log 八级、user/pid，以及连接数的真实上限。","frontmatter":{"title":"核心模块指令","description":"worker 进程与连接、events 块、error_log 八级、user/pid，以及连接数的真实上限。","source":"https://daiw.org/manual/nginx/core-module"},"headers":[],"relativePath":"manual/tools/nginx/core-module.md","filePath":"manual/tools/nginx/core-module.md"}'),r={name:"manual/tools/nginx/core-module.md"};function i(t,e,o,l,c,d){return n(),a("div",null,[...e[0]||(e[0]=[p(`<h1 id="核心模块指令" tabindex="-1">核心模块指令 <a class="header-anchor" href="#核心模块指令" aria-label="Permalink to &quot;核心模块指令&quot;">​</a></h1><p><code>ngx_core_module</code> 管的是<strong>进程模型与全局行为</strong>，绝大多数指令只能写在 <code>main</code> 上下文。</p><h2 id="worker-processes" tabindex="-1">worker_processes <a class="header-anchor" href="#worker-processes" aria-label="Permalink to &quot;worker\\_processes&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    worker_processes number | auto;</span></span>
<span class="line"><span>默认:    worker_processes 1;</span></span>
<span class="line"><span>上下文:  main</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>工作进程数。<strong>默认是 1</strong>——这个默认值在多核机器上严重浪费，几乎所有发行版的默认配置都会改掉它。</p><p><code>auto</code> 表示自动等于 CPU 核心数（1.2.5 起）。生产配置基本都写：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>worker_processes auto;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>nginx 是<strong>多进程单线程 + 事件驱动</strong>：一个 master 进程管理若干 worker，每个 worker 单线程跑事件循环。所以 worker 数超过核心数没有意义——它们会互相抢 CPU。</p><h2 id="worker-connections" tabindex="-1">worker_connections <a class="header-anchor" href="#worker-connections" aria-label="Permalink to &quot;worker\\_connections&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    worker_connections number;</span></span>
<span class="line"><span>默认:    worker_connections 512;</span></span>
<span class="line"><span>上下文:  events</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>每个 worker</strong> 能同时打开的最大连接数。默认 512。</p><p>理论最大并发连接：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>worker_processes × worker_connections</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>但这个数字有两个常被忽略的修正：</p><p><strong>一、反向代理场景要除以 2。</strong> 每个客户端连接会对应一个到上游的连接，两者都占 worker_connections 名额：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>最大并发客户端 ≈ worker_processes × worker_connections / 2</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>二、受系统文件描述符限制。</strong> 连接就是文件描述符，超过 <code>ulimit -n</code> 会报 <code>Too many open files</code>，与 nginx 配置无关。</p><h2 id="worker-rlimit-nofile" tabindex="-1">worker_rlimit_nofile <a class="header-anchor" href="#worker-rlimit-nofile" aria-label="Permalink to &quot;worker\\_rlimit\\_nofile&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    worker_rlimit_nofile number;</span></span>
<span class="line"><span>默认:    —</span></span>
<span class="line"><span>上下文:  main</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>给 worker 进程设置 <code>RLIMIT_NOFILE</code>（可打开文件数上限）。<strong>这是上一条的解药</strong>：不必去改系统 <code>ulimit</code>，nginx 自己抬高限制。</p><p>配置原则：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>worker_rlimit_nofile 65535;   # ≥ worker_connections，留出余量给日志、上游连接等</span></span>
<span class="line"><span>events {</span></span>
<span class="line"><span>    worker_connections 16384;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>只调 <code>worker_connections</code> 不调 <code>worker_rlimit_nofile</code> 是常见错误——配置里写着支持 6 万并发，实际到 1024 就开始报 <code>Too many open files</code>（多数系统 <code>ulimit -n</code> 默认 1024）。</p><h2 id="events-块" tabindex="-1">events 块 <a class="header-anchor" href="#events-块" aria-label="Permalink to &quot;events 块&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    events { ... }</span></span>
<span class="line"><span>上下文:  main</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>连接处理相关指令的容器。<strong>必需</strong>——没有 <code>events {}</code> 块 nginx 起不来。</p><h3 id="use" tabindex="-1">use <a class="header-anchor" href="#use" aria-label="Permalink to &quot;use&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    use method;</span></span>
<span class="line"><span>上下文:  events</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>指定连接处理方法（<code>epoll</code>、<code>kqueue</code>、<code>select</code>、<code>poll</code>、<code>eventport</code> 等）。</p><p><strong>通常不需要写</strong>——nginx 会自动选择当前平台最高效的方法。Linux 上是 <code>epoll</code>，BSD/macOS 上是 <code>kqueue</code>。手工指定只在调试或特殊平台时有用。</p><h3 id="multi-accept" tabindex="-1">multi_accept <a class="header-anchor" href="#multi-accept" aria-label="Permalink to &quot;multi\\_accept&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    multi_accept on | off;</span></span>
<span class="line"><span>默认:    multi_accept off;</span></span>
<span class="line"><span>上下文:  events</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><code>on</code> 时，worker 一次性接受<strong>所有</strong>待处理的新连接；<code>off</code> 时一次只接受一个。</p><p>高并发短连接场景开启可能降低 accept 开销，但也可能让某个 worker 一口气抢走大量连接造成不均衡。<strong>默认关闭是安全的</strong>，改动前应实测。</p><h3 id="accept-mutex" tabindex="-1">accept_mutex <a class="header-anchor" href="#accept-mutex" aria-label="Permalink to &quot;accept\\_mutex&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    accept_mutex on | off;</span></span>
<span class="line"><span>默认:    accept_mutex off;</span></span>
<span class="line"><span>上下文:  events</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>默认关闭</strong>（1.11.3 起改的默认值）。</p><p>它曾经用于解决「惊群」问题——多个 worker 同时被新连接唤醒。现代内核有 <code>EPOLLEXCLUSIVE</code>、nginx 也有 <code>reuseport</code>，这个互斥锁反而成了瓶颈，所以默认关掉了。</p><p>网上大量旧教程仍写着 <code>accept_mutex on;</code>。<strong>那是 1.11.3 之前的建议</strong>，现在照抄会降低性能。这类「过期最佳实践」是 nginx 配置里的普遍问题——本专栏所有默认值均以<a href="/Front2Full/manual/tools/nginx/">当前官方文档</a>为准。</p><h2 id="error-log" tabindex="-1">error_log <a class="header-anchor" href="#error-log" aria-label="Permalink to &quot;error\\_log&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    error_log file [level] [json];</span></span>
<span class="line"><span>默认:    error_log logs/error.log error;</span></span>
<span class="line"><span>上下文:  main, http, mail, stream, server, location</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>八个级别</strong>，官方原文按严重程度递增排列：</p><blockquote><p><code>debug</code>, <code>info</code>, <code>notice</code>, <code>warn</code>, <code>error</code>, <code>crit</code>, <code>alert</code>, or <code>emerg</code> Log levels above are listed in the order of increasing severity.</p></blockquote><table tabindex="0"><thead><tr><th>级别</th><th>含义</th></tr></thead><tbody><tr><td><code>debug</code></td><td>调试（<strong>需编译时 <code>--with-debug</code></strong>）</td></tr><tr><td><code>info</code></td><td>信息</td></tr><tr><td><code>notice</code></td><td>注意</td></tr><tr><td><code>warn</code></td><td>警告</td></tr><tr><td><code>error</code></td><td>错误（<strong>默认</strong>）</td></tr><tr><td><code>crit</code></td><td>严重</td></tr><tr><td><code>alert</code></td><td>需立即处理</td></tr><tr><td><code>emerg</code></td><td>紧急</td></tr></tbody></table><p><strong>指定某级别 = 记录该级别及更严重的全部</strong>。写 <code>warn</code> 会同时记 warn/error/crit/alert/emerg。</p><p>要点：</p><ul><li><strong><code>debug</code> 需要编译支持</strong>。没带 <code>--with-debug</code> 编译的 nginx 写了 <code>debug</code> 也只能输出到 <code>info</code> 级别。用 <code>nginx -V</code> 查编译参数。</li><li><strong><code>json</code> 参数</strong>是较新的结构化输出选项，便于日志采集。</li><li>它可以出现在 <code>location</code> 级——不同路径可以有不同的错误日志与级别。</li><li>特殊值 <code>error_log /dev/null crit;</code> 或 <code>error_log off;</code>——注意 <code>off</code> <strong>不是</strong>关闭日志的标准写法（它会创建一个名为 <code>off</code> 的文件），关闭应写 <code>error_log /dev/null crit;</code>。</li></ul><h2 id="user" tabindex="-1">user <a class="header-anchor" href="#user" aria-label="Permalink to &quot;user&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    user user [group];</span></span>
<span class="line"><span>默认:    user nobody nobody;</span></span>
<span class="line"><span>上下文:  main</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>worker 进程的运行身份。master 进程以 root 启动（为了绑定特权端口 <code>&lt;1024</code>），随后 worker <strong>降权</strong>到这里指定的用户。</p><p>省略 group 时用与 user 同名的组。</p><h2 id="pid" tabindex="-1">pid <a class="header-anchor" href="#pid" aria-label="Permalink to &quot;pid&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    pid file;</span></span>
<span class="line"><span>默认:    pid logs/nginx.pid;</span></span>
<span class="line"><span>上下文:  main</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>master 进程 PID 的记录文件。<code>nginx -s reload</code> 等信号操作依赖它——文件丢失或路径不对会导致「找不到进程」。</p><h2 id="daemon-与-master-process" tabindex="-1">daemon 与 master_process <a class="header-anchor" href="#daemon-与-master-process" aria-label="Permalink to &quot;daemon 与 master\\_process&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    daemon on | off;          默认: daemon on;</span></span>
<span class="line"><span>语法:    master_process on | off;  默认: master_process on;</span></span>
<span class="line"><span>上下文:  main</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>两者都<strong>只用于调试与容器</strong>：</p><ul><li><code>daemon off;</code>——不后台化，前台运行。<strong>容器里必须这么写</strong>，否则主进程退出容器就停了。</li><li><code>master_process off;</code>——不起 worker，master 自己处理请求。仅供调试，<strong>生产禁用</strong>。</li></ul><p>Docker 镜像的官方启动命令就是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nginx -g &quot;daemon off;&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="worker-cpu-affinity" tabindex="-1">worker_cpu_affinity <a class="header-anchor" href="#worker-cpu-affinity" aria-label="Permalink to &quot;worker\\_cpu\\_affinity&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    worker_cpu_affinity cpumask ...;</span></span>
<span class="line"><span>         worker_cpu_affinity auto [cpumask];</span></span>
<span class="line"><span>上下文:  main</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>把 worker 绑定到指定 CPU 核心，减少上下文切换与缓存失效。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>worker_processes    4;</span></span>
<span class="line"><span>worker_cpu_affinity 0001 0010 0100 1000;   # 4 个 worker 各绑一核</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>或让 nginx 自动分配：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>worker_processes    auto;</span></span>
<span class="line"><span>worker_cpu_affinity auto;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>仅 Linux/FreeBSD 有效</strong>，且只在 CPU 密集或超高并发场景下有可测收益。一般部署不必配。</p><h2 id="一份最小可用的顶层配置" tabindex="-1">一份最小可用的顶层配置 <a class="header-anchor" href="#一份最小可用的顶层配置" aria-label="Permalink to &quot;一份最小可用的顶层配置&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>user              nginx;</span></span>
<span class="line"><span>worker_processes  auto;</span></span>
<span class="line"><span>worker_rlimit_nofile 65535;</span></span>
<span class="line"><span>error_log         /var/log/nginx/error.log warn;</span></span>
<span class="line"><span>pid               /var/run/nginx.pid;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>events {</span></span>
<span class="line"><span>    worker_connections 16384;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>http {</span></span>
<span class="line"><span>    include       /etc/nginx/mime.types;</span></span>
<span class="line"><span>    default_type  application/octet-stream;</span></span>
<span class="line"><span>    # ...</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p>下一篇：<a href="/Front2Full/manual/tools/nginx/server-listen">server 与 listen</a>。</p>`,70)])])}const m=s(r,[["render",i]]);export{b as __pageData,m as default};
